    # your code
    pass

practice.solution:
def pb_filter(tpl, params):
    out = ''
    i = 0
    while i < len(tpl):
        if tpl[i:i + 2] == '{:':
            j = tpl.find('}', i)
            if j > 0:
                name = tpl[i + 2:j]
                if name in params:
                    v = params[name]
                    if v is None:
                        out += 'null'
                    elif v is True:
                        out += 'true'
                    elif v is False:
                        out += 'false'
                    elif isinstance(v, str):
                        out += "'" + v.replace("'", "\\'") + "'"
                    else:
                        out += str(v)
                else:
                    out += tpl[i:j + 1]
                i = j + 1
                continue
        out += tpl[i]
        i += 1
    return out

