practice.starter:
def check(rule, record, auth):
    # your code
    pass

practice.solution:
def check(rule, record, auth):
    def val(tok):
        tok = tok.strip()
        if tok[:1] == '"' or tok[:1] == "'":
            return tok[1:-1]
        if tok == 'true':
            return True
        if tok == 'false':
            return False
        if tok.startswith('@request.auth.'):
            return auth.get(tok[14:], '')
        try:
            return float(tok) if '.' in tok else int(tok)
        except ValueError:
            pass
        return record.get(tok, '')

    def like(a, b):
        s = str(a).lower()
        p = str(b).lower()
        core = p.strip('%')
        if p.startswith('%') and p.endswith('%') and len(p) > 1:
            return core in s
        if p.endswith('%'):
            return s.startswith(core)
        if p.startswith('%'):
            return s.endswith(core)
        return core in s

    def clause(c):
        c = c.strip()
        for op in ['!=', '>=', '<=', '!~', '=', '>', '<', '~']:
            parts = c.split(' ' + op + ' ', 1)
            if len(parts) == 2:
                a = val(parts[0])
                b = val(parts[1])
                if op == '=':
                    return a == b
                if op == '!=':
                    return a != b
                if op == '~':
                    return like(a, b)
                if op == '!~':
                    return not like(a, b)
                try:
                    if op == '>':
                        return a > b
                    if op == '>=':
                        return a >= b
                    if op == '<':
                        return a < b
                    return a <= b
                except TypeError:
                    return False
        return False

    for alt in rule.split('||'):
        ok = True
        for c in alt.split('&&'):
            if not clause(c):
                ok = False
                break
        if ok:
            return True
    return False

