def token_status(token, now):
    # your code
    pass

practice.solution:
def token_status(token, now):
    import json
    parts = token.split('.')
    if len(parts) != 3:
        return 'malformed'
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    s = parts[1].replace('-', '+').replace('_', '/')
    bits = 0
    nbits = 0
    out = ''
    try:
        for ch in s:
            if ch == '=':
                break
            v = alphabet.find(ch)
            if v < 0:
                return 'malformed'
            bits = (bits << 6) | v
            nbits += 6
            if nbits >= 8:
                nbits -= 8
                out += chr((bits >> nbits) & 255)
                bits &= (1 << nbits) - 1
        data = json.loads(out)
        exp = data.get('exp')
    except Exception:
        return 'malformed'
    if not isinstance(exp, int) or isinstance(exp, bool):
        return 'malformed'
    if now >= exp:
        return 'expired'
    return 'valid'

