    pass

practice.solution:
def parse_thumb(spec):
    mode = ''
    core = spec
    if spec[-1:] in ('t', 'b', 'f'):
        mode = spec[-1]
        core = spec[:-1]
    parts = core.split('x')
    if len(parts) != 2 or not parts[0].isdigit() or not parts[1].isdigit():
        return []
    w = int(parts[0])
    h = int(parts[1])
    if w == 0 and h == 0:
        return []
    if w == 0 or h == 0:
        return [w, h, 'resize']
    return [w, h, mode or 'center']

