def run_chain(handlers):
    log = []
    def run(i):
        if i == len(handlers):
            log.append('INSERT')
            return
        log.append(str(i) + ':before')
        if handlers[i]:
            run(i + 1)
            log.append(str(i) + ':after')
    run(0)
    return log

