def cron_match(expr, minute, hour, dom, month, dow):
    fields = expr.split()
    values = [minute, hour, dom, month, dow]
    starts = [0, 0, 1, 1, 0]
    for i in range(5):
        v = values[i]
        ok = False
        for part in fields[i].split(','):
            if part == '*':
                ok = True
            elif part.startswith('*/'):
                if (v - starts[i]) % int(part[2:]) == 0:
                    ok = True
            elif '-' in part:
                a, b = part.split('-')
                if int(a) <= v <= int(b):
                    ok = True
            elif int(part) == v:
                ok = True
        if not ok:
            return False
    return True

